Object.assign(View, {
  renderSnakeIconAnimation(canvas) {
    const ctx = canvas.getContext("2d");
    const cx = canvas.width / 2;
    const cy = canvas.height / 2;
    const radius = 17;
    const numPoints = 24;

    const path = [];
    for (let i = 0; i < numPoints; i++) {
      const angle = (i / numPoints) * Math.PI * 2;
      path.push({
        x: cx + radius * Math.cos(angle),
        y: cy + radius * Math.sin(angle)
      });
    }

    let angleIndex = 0;
    const snakeLength = 6;

    const interval = setInterval(() => {
      if (!document.body.contains(canvas)) {
        clearInterval(interval);
        return;
      }
      const style = getComputedStyle(document.body);
      const ink = style.getPropertyValue('--ink').trim() || '#090b0a';
      const line = style.getPropertyValue('--line').trim() || '#1b221d';
      const green = style.getPropertyValue('--green').trim() || '#20ef4f';
      const cyan = style.getPropertyValue('--cyan').trim() || '#91f3a8';

      angleIndex = (angleIndex + 1) % path.length;

      ctx.fillStyle = ink;
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      ctx.strokeStyle = line;
      ctx.lineWidth = 0.5;
      ctx.beginPath();
      ctx.arc(cx, cy, radius, 0, Math.PI * 2);
      ctx.stroke();

      ctx.fillStyle = cyan;
      ctx.shadowColor = cyan;
      ctx.shadowBlur = 8;
      ctx.fillRect(cx - 3, cy - 3, 6, 6);
      ctx.shadowBlur = 0;

      for (let i = 0; i < snakeLength; i++) {
        const ptIdx = (angleIndex - i + path.length) % path.length;
        const pt = path[ptIdx];

        ctx.fillStyle = i === 0 ? cyan : green;
        if (i === 0) {
          ctx.shadowColor = green;
          ctx.shadowBlur = 6;
        }

        ctx.beginPath();
        ctx.arc(pt.x, pt.y, 3.5, 0, Math.PI * 2);
        ctx.fill();

        if (i === 0) ctx.shadowBlur = 0;
      }
    }, 70);
  }
});

